    private String financialFrom="",financialTo="",financialBucket="sales";
    private int financialPage=0,financialRevision=0;
    private LinearLayout financialResults;
    private void openFinancialSummary(){setFinancialPeriod("month");}
    private void setFinancialPeriod(String kind){
        java.util.TimeZone zone=java.util.TimeZone.getTimeZone("Asia/Jerusalem");java.util.Calendar date=java.util.Calendar.getInstance(zone);java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);format.setTimeZone(zone);financialTo=format.format(date.getTime());
        if("week".equals(kind))date.add(java.util.Calendar.DAY_OF_MONTH,1-date.get(java.util.Calendar.DAY_OF_WEEK));if("month".equals(kind))date.set(java.util.Calendar.DAY_OF_MONTH,1);financialFrom=format.format(date.getTime());if("all".equals(kind)){financialFrom="";financialTo="";}financialPage=0;showFinancialSummary();
    }
    private void showFinancialSummary(){
        buildShell("סיכום כספי",this::showAdminHome,false);LinearLayout quick=new LinearLayout(this);String[] labels={"היום","השבוע","החודש","כל התקופה"},keys={"today","week","month","all"};for(int i=0;i<keys.length;i++){final String key=keys[i];Button b=button(labels[i],Color.WHITE,blue);b.setOnClickListener(v->setFinancialPeriod(key));quick.addView(b,new LinearLayout.LayoutParams(0,dp(52),1));}content.addView(quick);
        LinearLayout range=new LinearLayout(this);EditText from=input("מתאריך YYYY-MM-DD"),to=input("עד תאריך YYYY-MM-DD");from.setText(financialFrom);to.setText(financialTo);range.addView(from,new LinearLayout.LayoutParams(0,-2,1));range.addView(to,new LinearLayout.LayoutParams(0,-2,1));content.addView(range);Button apply=button("הצג סיכום",blue,Color.WHITE);apply.setOnClickListener(v->{financialFrom=from.getText().toString().trim();financialTo=to.getText().toString().trim();financialPage=0;loadFinancialSummary();});content.addView(apply);
        content.addView(text("לפי הרישומים בחנות; לא אישור לזיכוי בבנק. יתרה = מכירות + הכנסות אחרות פחות רכישת סחורה והוצאות. רווח = מכירות פחות עלות המוצרים שנמכרו והוצאות אחרות.",15,false));financialResults=baseRoot();content.addView(financialResults);loadFinancialSummary();
    }
    private String financialMoney(JSONObject row,String key){return row.isNull(key)?"אין מספיק נתונים":String.format(Locale.ROOT,"%,.2f ₪",row.optDouble(key));}
    private void loadFinancialSummary(){
        final LinearLayout host=financialResults;final int revision=++financialRevision;host.removeAllViews();host.addView(text("טוען סיכום...",18,false));
        try{final JSONObject body=new JSONObject().put("p_from",financialFrom.isEmpty()?JSONObject.NULL:financialFrom).put("p_to",financialTo.isEmpty()?JSONObject.NULL:financialTo).put("p_bucket",financialBucket).put("p_page",financialPage);io.execute(()->{try{JSONObject result=new JSONObject(requestRaw("POST","/rest/v1/rpc/get_financial_summary",body,true));main.post(()->{if(revision!=financialRevision||!host.isAttachedToWindow())return;host.removeAllViews();JSONObject summary=result.optJSONObject("summary");if(summary==null)return;
            String[] keys={"sales","other_income","purchases","expenses","balance","known_cost","gross_profit","net_profit"},titles={"מכירות ששולמו","הכנסות אחרות","רכישת סחורה","הוצאות אחרות","יתרת הכנסות פחות הוצאות","עלות ידועה של מוצרים שנמכרו","רווח גולמי משוער","רווח משוער לאחר הוצאות"},buckets={"sales","other_income","purchases","expenses","balance","cost","cost","profit"};
            for(int i=0;i<keys.length;i+=2){LinearLayout pair=new LinearLayout(this);for(int j=i;j<Math.min(i+2,keys.length);j++){final String bucket=buckets[j];Button tile=button(titles[j]+"\n"+financialMoney(summary,keys[j])+"\nלחץ לפירוט",Color.rgb(233,245,240),Color.rgb(22,72,59));tile.setTextSize(17);tile.setOnClickListener(v->{financialBucket=bucket;financialPage=0;loadFinancialSummary();});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(115),1);lp.setMargins(dp(4),dp(4),dp(4),dp(4));pair.addView(tile,lp);}host.addView(pair);}
            if(summary.optInt("missing_count")>0){host.addView(text("ב־"+summary.optInt("missing_count")+" עסקאות חסרה עלות מלאה, ולכן לא מוצג רווח כולל. העלות הידועה אינה כוללת עלויות חסרות.",18,true));Button missing=button("הצג עסקאות עם מידע חסר",Color.WHITE,blue);missing.setOnClickListener(v->{financialBucket="missing";financialPage=0;loadFinancialSummary();});host.addView(missing);}
            host.addView(text("הכנסות ידניות אינן נכללות ברווח מהמכירות. החזרים וזיכויים לבנק אינם מופרדים כיום. עמלות והוצאות נכללות רק אם נרשמו.",15,false));host.addView(text("מכירות לפי אמצעי תשלום",21,true));JSONArray methods=result.optJSONArray("methods");if(methods!=null)for(int i=0;i<methods.length();i++){JSONObject m=methods.optJSONObject(i);if(m!=null)host.addView(text(m.optString("payment_method")+" · "+financialMoney(m,"amount"),17,false));}host.addView(text(summary.optInt("verified_count")+" מתוך "+summary.optInt("sale_count")+" מכירות מסומנות כאומתות מול נדרים. היתר עשויות לכלול מזומן ומכירות מיוחדות.",15,false));
            String title="עסקאות עם עלות חסרה";for(int i=0;i<buckets.length;i++)if(buckets[i].equals(financialBucket)){title=titles[i];break;}host.addView(text(title+" · "+result.optInt("count")+" תנועות",22,true));JSONArray rows=result.optJSONArray("rows");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;LinearLayout c=card();c.addView(text(row.optString("entry_date")+" · "+row.optString("description")+" · "+financialMoney(row,"amount"),18,true));Button detail=button("פתיחת פירוט",Color.WHITE,blue);detail.setOnClickListener(v->showFinancialDetail(row));c.addView(detail);host.addView(c);}if(rows==null||rows.length()==0)host.addView(text("אין תנועות בתקופה שנבחרה",17,false));LinearLayout nav=new LinearLayout(this);Button prev=button("הקודם",Color.WHITE,blue),next=button("הבא",Color.WHITE,blue);prev.setEnabled(financialPage>0);next.setEnabled((financialPage+1)*50<result.optInt("count"));prev.setOnClickListener(v->{financialPage--;loadFinancialSummary();});next.setOnClickListener(v->{financialPage++;loadFinancialSummary();});nav.addView(prev,new LinearLayout.LayoutParams(0,dp(50),1));nav.addView(next,new LinearLayout.LayoutParams(0,dp(50),1));host.addView(nav);
        });}catch(Exception e){main.post(()->{if(revision==financialRevision&&host.isAttachedToWindow()){host.removeAllViews();host.addView(text("לא ניתן לטעון סיכום: "+safeMsg(e),17,false));}});}});}catch(Exception e){host.addView(text("טווח התאריכים אינו תקין",17,false));}
    }
    private void showFinancialDetail(JSONObject row){
        ScrollView scroll=new ScrollView(this);LinearLayout box=baseRoot();box.setPadding(dp(16),dp(12),dp(16),dp(12));scroll.addView(box);box.addView(text(row.optString("description")+"\n"+row.optString("entry_date")+" · "+row.optString("payment_method")+"\n"+financialMoney(row,"amount"),20,true));if("sales".equals(row.optString("bucket"))){box.addView(text("עלות ידועה: "+financialMoney(row,"known_cost")+(row.optBoolean("missing_cost")?" · חסר מידע לחישוב רווח":""),17,true));box.addView(text("ארבע ספרות: "+(row.isNull("card_last4")?"—":row.optString("card_last4"))+" · אסמכתא: "+(row.isNull("payment_reference")?"—":row.optString("payment_reference")),16,false));JSONArray items=row.optJSONArray("items");if(items!=null)for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item!=null)box.addView(text(item.optString("product_name")+" × "+item.optInt("quantity")+"\nמכירה: "+financialMoney(item,"line_total")+" · עלות ליחידה בזמן המכירה: "+financialMoney(item,"unit_cost"),17,false));}}new AlertDialog.Builder(this).setTitle("פירוט תנועה").setView(scroll).setPositiveButton("סגור",null).show();
    }
